/*
 * A290538  Let S be the sequence generated by these rules: 0 is in S, and if
 *          z is in S, then z + 1 and z * (1+i) are in S (where i denotes the
 *          imaginary unit), and duplicates are deleted as they occur; a(n) =
 *          the square of the norm of the n-th term of S.
 * https://oeis.org/A290538
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, look
 * Formula:   not stated
 * Range:     u8 n <= 120, u16 n <= 8558, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   _hash64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A290538 – norm squared of the Gaussian integers generated
 * by the rules: 0 is in S; if z∈S then z+1 and z*(1+i) are in S.
 * Duplicates are removed immediately.  The sequence lists the norm² of
 * the elements in the order they are dequeued from a FIFO queue.
 *
 * The code uses a breadth‑first search:
 *   • A hash table (open addressing) keeps all visited points.
 *   • A simple queue holds the frontier.
 *   • The first element 0 is already part of the sequence.
 *   • When a node is dequeued it becomes the next sequence element;
 *     its children are generated and enqueued only if unseen.
 *
 * For the norm squared we use absolute values of the real and imaginary
 * parts.  All arithmetic on seq_t is performed with the ordinary +,-,*
 * operators, as required.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/_hash64.h"

/* ------------------------------------------------------------------ */
/* Data structures                                                     */
/* ------------------------------------------------------------------ */
typedef struct { int64_t x; int64_t y; } Complex;

/* ------------------------------------------------------------------ */
/* Simple open‑addressing hash table for visited points               */
/* ------------------------------------------------------------------ */
#define HASH_BITS  20                     /* 1 << 20 slots … > 1M */
#define HASH_CAP   (1U << HASH_BITS)
static int64_t *h_x = NULL;
static int64_t *h_y = NULL;
static uint8_t *h_used = NULL;

/* Insert (a,b) if not present.  Return true iff inserted anew.   */
static bool _hash_insert(int64_t a, int64_t b)
{
    uint64_t h = _hash64(a, b);
    size_t idx = h & (HASH_CAP - 1);
    while (h_used[idx]) {
        if (h_x[idx] == a && h_y[idx] == b)
            return false;                 /* already present */
        idx = (idx + 1) & (HASH_CAP - 1);
    }
    h_x[idx] = a;
    h_y[idx] = b;
    h_used[idx] = 1;
    return true;
}

/* ------------------------------------------------------------------ */
/* Queue (FIFO) for breadth‑first traversal                           */
/* ------------------------------------------------------------------ */
static Complex *queue = NULL;
static size_t q_head = 0, q_tail = 0;
static size_t q_cap = 0;

/* Resize queue so it can hold at least `need` elements.              */
static void _grow_queue(size_t need)
{
    if (q_cap >= need) return;
    size_t new_cap = (q_cap == 0) ? 16 : q_cap << 1;
    while (new_cap < need) new_cap <<= 1;
    queue = (Complex *)realloc(queue, new_cap * sizeof(Complex));
    q_cap = new_cap;
}

/* ------------------------------------------------------------------ */
/* Storage for the sequence values                                     */
/* ------------------------------------------------------------------ */
static seq_t *vals = NULL;
static size_t vals_size = 0;
static size_t vals_cap = 0;

/* Ensure the values array can hold at least `need` elements.          */
static void _grow_vals(size_t need)
{
    if (vals_cap >= need) return;
    size_t new_cap = (vals_cap == 0) ? 16 : vals_cap << 1;
    while (new_cap < need) new_cap <<= 1;
    vals = (seq_t *)realloc(vals, new_cap * sizeof(seq_t));
    vals_cap = new_cap;
}

/* ------------------------------------------------------------------ */
/* Compute the squared norm of a complex point (without overflow)     */
/* ------------------------------------------------------------------ */
static seq_t _normsq(const Complex *c)
{
    /* take absolute values before squaring */
    int64_t ax = c->x;
    int64_t ay = c->y;
    if (ax < 0) ax = -ax;
    if (ay < 0) ay = -ay;
    seq_t sx = (seq_t)ax;
    seq_t sy = (seq_t)ay;
    return sx * sx + sy * sy;
}

/* ------------------------------------------------------------------ */
/* The required sequence function                                      */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                 /* out of range – return 0 */

    /* one‑time global initialization */
    static bool initialized = false;
    static bool first_pop = true;         /* skip norm for the 0 we already stored */

    if (!initialized) {
        /* allocate hash table */
        h_x    = (int64_t *)malloc(HASH_CAP * sizeof(int64_t));
        h_y    = (int64_t *)malloc(HASH_CAP * sizeof(int64_t));
        h_used = (uint8_t *)calloc(HASH_CAP, sizeof(uint8_t));

        /* enqueue the initial element 0 */
        _grow_queue(16);
        queue[q_tail].x = 0;
        queue[q_tail].y = 0;
        q_tail++;

        /* mark 0 as visited */
        _hash_insert(0, 0);

        /* store first value */
        _grow_vals(16);
        vals[0] = (seq_t)0;
        vals_size = 1;

        initialized = true;
    }

    /* generate extra terms until we have at least n of them */
    while (vals_size < n) {
        /* dequeue the next node in the sequence order */
        Complex z = queue[q_head++];

        /* record the value of this node (except for the very first pop) */
        if (!first_pop) {
            _grow_vals(vals_size + 1);
            vals[vals_size++] = _normsq(&z);
        } else {
            first_pop = false;           /* skip 0 (already stored) */
        }

        /* generate children from z */
        /* 1. z + 1 */
        Complex z1 = { z.x + 1, z.y };
        if (_hash_insert(z1.x, z1.y)) {
            _grow_queue(q_tail + 1);
            queue[q_tail++] = z1;
        }

        /* 2. z * (1 + i)  →  (x – y) + (x + y)i */
        Complex z2 = { z.x - z.y, z.x + z.y };
        if (_hash_insert(z2.x, z2.y)) {
            _grow_queue(q_tail + 1);
            queue[q_tail++] = z2;
        }
    }

    return vals[n - 1];
}
